def fnv1a32(text: str) -> int:
    h = 0x811C9DC5
    for b in text.encode("utf-8"):
        h ^= b
        h = (h * 0x01000193) & 0xFFFFFFFF
    return h


def resolve_sdf_glyph_id(domain_id: int, qid: int, l1: str, l2: str, prompt: str) -> str:
    triplet = DOMAIN_SDF_GLYPHS[domain_id]
    blob = f"{l1} {l2} {prompt}"
    for glyph_id, rx in GLYPH_KEYWORD_RULES:
        if glyph_id in triplet and rx.search(blob):
            return glyph_id
    return triplet[fnv1a32(f"GLYPH:{qid}:{l1}") % 3]


def load_canonical_taxonomy() -> tuple[dict[str, dict[str, Any]], list[str], dict[int, list[str]], set[str]]:
    with open(TAX_PATH, "r", encoding="utf-8") as f:
        tax = json.load(f)
    l2_meta: dict[str, dict[str, Any]] = {}
    ordered_l2s: list[str] = []
    domain_l2s: dict[int, list[str]] = {}
    all_l1_ids: set[str] = set()
    for dom in tax["domains"]:
        did = int(dom["l0Domain"])
        domain_l2s[did] = []
        for l1 in dom["l1Subcategories"]:
            l1_id = str(l1["id"])
            l1_name = str(l1["name"])
            all_l1_ids.add(l1_id)
            for l2 in l1["l2Topics"]:
                l2_id = str(l2["id"])
                l2_name = str(l2["name"])
                l2_meta[l2_id] = {
                    "domainId": did,
                    "l1Id": l1_id,
                    "l1Category": l1_name,
                    "subcatId": l2_id,
                    "l2Id": l2_id,
                    "l2Subcategory": l2_name,
                    "l2Category": l2_name,
                }
                ordered_l2s.append(l2_id)
                domain_l2s[did].append(l2_id)
    return l2_meta, ordered_l2s, domain_l2s, all_l1_ids


def build_bundle() -> dict[str, Any]:
    l2_meta, ordered_l2s, _domain_l2s, _all_l1_ids = load_canonical_taxonomy()
    raw_items: list[dict[str, Any]] = json.loads(CURATED_BANK_JSON)
    grouped: dict[str, list[dict[str, Any]]] = {sid: [] for sid in ordered_l2s}
    for item in raw_items:
        sid = item["subcatId"]
        if sid not in grouped:
            raise ValueError(f"Unknown canonical subcatId: {sid!r}")
        grouped[sid].append(item)

    questions: list[dict[str, Any]] = []
    by_domain: Counter[str] = Counter()
    by_l1: Counter[str] = Counter()
    by_subcat: Counter[str] = Counter()
    qid = QID_BASE

    for sid in ordered_l2s:
        meta = l2_meta[sid]
        did = meta["domainId"]
        for local_idx, item in enumerate(grouped[sid], start=1):
            prompt = re.sub(r"\s+", " ", item["prompt"].strip())
            answer = re.sub(r"\s+", " ", item["answerCorrect"].strip())
            raw_dists = item["distractors"]
            plaus_scores = (0.86, 0.79, 0.72)
            distractors = [
                {
                    "text": re.sub(r"\s+", " ", (d["text"] if isinstance(d, dict) else str(d)).strip()),
                    "plausibility": plaus_scores[i],
                }
                for i, d in enumerate(raw_dists[:3])
            ]
            clues = [re.sub(r"\s+", " ", str(c).strip()) for c in item["clues"][:2]]
            why = re.sub(r"\s+", " ", item["whyExplanation"].strip())
            irt_b = round(float(item["irtB"]), 2)
            tone = str(item.get("tone", "PRESTIGE")).upper()
            if tone not in ("PRESTIGE", "WITTY", "THRILLER", "CRYPTIC"):
                tone = "PRESTIGE"
            glyph_hint = DOMAIN_GLYPH_HINTS[did]
            glyph_id = resolve_sdf_glyph_id(did, qid, meta["l1Category"], meta["l2Subcategory"], prompt)

            rec = {
                "qid": qid,
                "l0Domain": did,
                "domainId": did,
                "l1Id": meta["l1Id"],
                "l1Category": meta["l1Category"],
                "l2Id": sid,
                "subcatId": sid,
                "l2Category": meta["l2Category"],
                "l2Subcategory": meta["l2Subcategory"],
                "microTopicId": f"jeop_{sid}_{local_idx:02d}",
                "archetype": "SIGHTLINE_LOCK",
                "irtB": irt_b,
                "irtA": 1.28,
                "prompt": prompt,
                "answerCorrect": answer,
                "distractors": distractors,
                "clues": clues,
                "whyExplanation": why,
                "glyphHint": glyph_hint,
                "glyphId": glyph_id,
                "regions": ["GLOBAL"],
                "narrativeTags": ["LATERAL_DEDUCTION", DOMAIN_FACTION_TAG[did]],
                "tone": tone,
                "freshness": "EVERGREEN",
                "sourceTier": "GOLD_CURATED",
            }
            questions.append(rec)
            by_domain[str(did)] += 1
            by_l1[meta["l1Id"]] += 1
            by_subcat[sid] += 1
            qid += 1

    return {
        "schemaVersion": SCHEMA_VERSION,
        "generatedAt": GENERATED_AT,
        "qidRange": [QID_BASE, qid - 1],
        "totalCount": len(questions),
        "totalQuestions": len(questions),
        "coverage": {
            "domains": len(by_domain),
            "l1Categories": len(by_l1),
            "l2Subcategories": len(by_subcat),
        },
        "counts": {
            "byDomain": {str(d): by_domain[str(d)] for d in range(12)},
            "byArchetype": {"SIGHTLINE_LOCK": len(questions)},
            "byL1": dict(sorted(by_l1.items())),
            "bySubcatId": dict(sorted(by_subcat.items())),
        },
        "questions": questions,
    }


def _singular_stem(tok: str) -> str:
    if len(tok) > 5 and tok.endswith("ies"):
        return tok[:-3] + "y"
    if len(tok) > 5 and tok.endswith("es"):
        return tok[:-2]
    if len(tok) > 4 and tok.endswith("s") and not tok.endswith("ss"):
        return tok[:-1]
    return tok


def _has_word_stem(hay_low: str, stem: str) -> bool:
    idx = hay_low.find(stem)
    while idx != -1:
        before_ok = idx == 0 or not hay_low[idx - 1].isalnum()
        if before_ok:
            after_pos = idx + len(stem)
            tail = hay_low[after_pos : after_pos + 3]
            if tail == "" or re.match(r"^[^a-z0-9]|^(?:s|es|ed|er|y)(?:[^a-z0-9]|$)", tail):
                return True
        idx = hay_low.find(stem, idx + 1)
    return False


def _check_text(text: str, domain_id: int, field: str, ctx: str) -> list[str]:
    errs: list[str] = []
    if not isinstance(text, str) or not text.strip():
        return [f"{ctx} [{field}]: empty text"]
    if "," in text:
        for rx in (RE_YEAR_COMMA_PREFIX, RE_YEAR_COMMA_SUFFIX, RE_YEAR_COMMA_DECADE, RE_YEAR_COMMA_PAREN, RE_YEAR_COMMA_RANGE):
            for m in rx.finditer(text):
                yr = int((m.group(1) or m.group(5) or "0") + (m.group(2) or m.group(6) or "000"))
                if 1000 <= yr <= 2099 and not NON_YEAR_AFTER_NUM.match(text[m.end():]):
                    errs.append(f"{ctx} [{field}] DATE_YEAR_COMMA: {m.group(0)!r}")
                    break
        m = RE_MALFORMED_COMMA_NUM.search(text)
        if m:
            errs.append(f"{ctx} [{field}] MALFORMED_COMMA_NUM: {m.group(0)!r}")
    if "." in text:
        for cm in RE_CITY_PERIOD_STATE.finditer(text):
            cw, st = cm.group(1), cm.group(2)
            if st in US_CA_STATE_CODES and cw.lower() not in ABBREV_BEFORE_PERIOD:
                after_c = text[cm.end():cm.end()+1]
                if not (st in AMBIGUOUS_STATE_WORDS and not re.match(r"^[?!,)]|$", after_c)):
                    errs.append(f"{ctx} [{field}] CITY_PERIOD_STATE: {cm.group(0)!r}")
        if RE_DOUBLE_DOT_BAD.search(text) and not re.search(r"Mm\.\. Food|Dil Se\.\.|Hain Koun\.\.!", text):
            errs.append(f"{ctx} [{field}] DOUBLE_DOT")
        if "?" in text and RE_BAD_DOT_Q.search(text):
            m = RE_BAD_DOT_Q.search(text)
            if m and m.group(1).lower() not in ABBREV_BEFORE_PERIOD:
                errs.append(f"{ctx} [{field}] BAD_DOT_Q: {m.group(0)!r}")
    if RE_BAD_PUNCT_SEQ.search(text):
        errs.append(f"{ctx} [{field}] BAD_PUNCT_SEQ")
    if RE_BAD_DOUBLE_BANG.search(text):
        errs.append(f"{ctx} [{field}] BAD_DOUBLE_BANG")
    if RE_SPACE_BEFORE_PUNCT.search(text):
        m = RE_SPACE_BEFORE_PUNCT.search(text)
        if not (domain_id == 11 and any(c in m.group(0) for c in ".:")):
            errs.append(f"{ctx} [{field}] SPACE_BEFORE_PUNCT: {m.group(0)!r}")
    if RE_HTML_ENTITY.search(text):
        errs.append(f"{ctx} [{field}] HTML_ENTITY")
    if RE_LATEX_SUB_SUP.search(text):
        errs.append(f"{ctx} [{field}] RAW_LATEX")
    if RE_UNRESOLVED_TPL.search(text):
        errs.append(f"{ctx} [{field}] UNRESOLVED_TPL")
    if RE_CORRUPT_QMARK.search(text):
        errs.append(f"{ctx} [{field}] CORRUPT_QMARK")
    if RE_DOUBLE_SPACE.search(text):
        errs.append(f"{ctx} [{field}] DOUBLE_SPACE")
    for dw in RE_DOUBLE_WORD.finditer(text):
        pair = dw.group(0)
        if re.match(r"^(?:in In|on On|for For|of Of|to To|from From|at At|by By|with With|the The|IS is|for FOR|Is Is|The The)$", pair):
            if pair == "the The" and not re.search(r"band|album|song", text, re.I):
                errs.append(f"{ctx} [{field}] DOUBLE_WORD: {pair!r}")
            continue
        errs.append(f"{ctx} [{field}] DOUBLE_WORD: {pair!r}")
    for am in RE_A_VOWEL.finditer(text):
        w = am.group(2)
        if RE_A_VOWEL_EXCEPT.match(w) or re.match(r"^U[A-Z]+$", w):
            continue
        before = text[max(0, am.start() - 18) : am.start()]
        if RE_LABEL_BEFORE_A.search(before):
            continue
        if am.group(1) == "A" and w[0].isupper() and am.start() > 0 and not re.search(r'[.?!:\n"“]\s*$', text[:am.start()]):
            continue
        errs.append(f"{ctx} [{field}] ARTICLE_A_VOWEL: {am.group(0)!r}")
    for am in RE_AN_CONSONANT.finditer(text):
        w = am.group(2)
        if RE_AN_CONSONANT_EXCEPT.match(w) or re.match(r"^[FHLMNRSX][A-Z0-9-]+$", w):
            continue
        if w[0].isupper() and not re.match(
            r"^(?:Russian|French|German|Spanish|Italian|British|Japanese|Chinese|Korean|Polish|Dutch|Greek|Swiss|Swedish|Norwegian|Danish|Finnish|Czech|Turkish|Persian|Roman|Latin|Catholic|Christian|Jewish|Muslim|Buddhist|Hindu|Nordic|Celtic|Slavic|Baltic|Balkan|Pacific|Caribbean|Brazilian|Mexican|Canadian)$",
            w,
        ):
            continue
        errs.append(f"{ctx} [{field}] ARTICLE_AN_CONSONANT: {am.group(0)!r}")
    return errs


def verify_pack(bundle: dict[str, Any], check_disk_determinism: bool = True) -> list[str]:
    errs: list[str] = []
    l2_meta, ordered_l2s, domain_l2s, all_l1_ids = load_canonical_taxonomy()
    questions = bundle.get("questions", [])
    if len(questions) < 1600:
        errs.append(f"Total question count {len(questions)} < 1600")

    if check_disk_determinism:
        expected = build_bundle()
        if bundle != expected:
            errs.append("On-disk JSON differs from deterministic build_bundle() output")

    # External QID collision ranges
    forbidden_ranges: list[tuple[str, int, int]] = [
        ("questions.json", 1, 20_165),
        ("gold_venue_packs.json", 50_001, 50_712),
        ("CODEX_SYNTHESIS", 995_000, 1_045_399),
        ("visual_globe_packs.json", 1_070_001, 1_079_999),
        ("INSTANT_COLD_OPEN_PRISMS", 1_080_001, 1_080_099),
    ]
    if SHARD_MANIFEST_PATH.exists():
        sm = json.loads(SHARD_MANIFEST_PATH.read_text(encoding="utf-8"))
        qr = sm.get("qidRange", [60_000, 989_563])
        forbidden_ranges.append(("shard_manifest.json", int(qr[0]), int(qr[1])))
    if TAX_PATH.exists():
        tx = json.loads(TAX_PATH.read_text(encoding="utf-8"))
        qr = tx.get("qidRange", [1_100_000, 1_391_712])
        forbidden_ranges.append(("taxonomy_tree.json", int(qr[0]), int(qr[1])))

    seen_qids: set[int] = set()
    seen_prompts: set[str] = set()
    by_domain: Counter[int] = Counter()
    by_l1: Counter[str] = Counter()
    by_l2: Counter[str] = Counter()
    subcat_ans: Counter[tuple[str, str]] = Counter()
    valid_glyphs = {g for trip in DOMAIN_SDF_GLYPHS.values() for g in trip}

    for q in questions:
        qid = q.get("qid")
        ctx = f"QID {qid}"
        if not isinstance(qid, int) or not (QID_BASE <= qid <= QID_MAX_ALLOWED):
            errs.append(f"{ctx}: qid outside [{QID_BASE}..{QID_MAX_ALLOWED}]")
        elif qid in seen_qids:
            errs.append(f"{ctx}: duplicate QID")
        else:
            seen_qids.add(qid)
            for label, lo, hi in forbidden_ranges:
                if lo <= qid <= hi:
                    errs.append(f"{ctx}: collides with {label} [{lo}..{hi}]")

        sub = q.get("subcatId")
        if sub not in l2_meta:
            errs.append(f"{ctx}: invalid subcatId {sub!r}")
            continue
        meta = l2_meta[sub]
        did = meta["domainId"]
        if q.get("l0Domain") != did or q.get("domainId") != did:
            errs.append(f"{ctx}: domain mismatch")
        if q.get("l1Id") != meta["l1Id"] or q.get("l1Category") != meta["l1Category"]:
            errs.append(f"{ctx}: L1 mismatch")
        if q.get("l2Id") != sub or q.get("l2Subcategory") != meta["l2Subcategory"]:
            errs.append(f"{ctx}: L2 mismatch")
        if q.get("archetype") != "SIGHTLINE_LOCK":
            errs.append(f"{ctx}: unexpected archetype {q.get('archetype')!r}")
        if q.get("glyphId") not in valid_glyphs:
            errs.append(f"{ctx}: invalid glyphId {q.get('glyphId')!r}")

        by_domain[did] += 1
        by_l1[meta["l1Id"]] += 1
        by_l2[sub] += 1

        prompt = str(q.get("prompt", "")).strip()
        ans = str(q.get("answerCorrect", "")).strip()
        dists = q.get("distractors", [])
        clues = q.get("clues", [])
        why = str(q.get("whyExplanation", "")).strip()
        irt_b = q.get("irtB")

        if not isinstance(irt_b, (int, float)) or not (-1.4 <= float(irt_b) <= 2.1):
            errs.append(f"{ctx}: irtB {irt_b!r} out of [-1.4, 2.1]")
        if len(prompt) < 55 or len(prompt) > 225:
            errs.append(f"{ctx}: prompt len {len(prompt)} out of 55..225")
        if RE_FLAT_OPENING.match(prompt):
            errs.append(f"{ctx}: flat prompt opening: {prompt[:60]!r}")
        pnorm = re.sub(r"\s+", " ", prompt.lower())
        if pnorm in seen_prompts:
            errs.append(f"{ctx}: duplicate prompt")
        seen_prompts.add(pnorm)

        subcat_ans[(sub, ans.lower())] += 1
        if subcat_ans[(sub, ans.lower())] > 1:
            errs.append(f"{ctx}: duplicate answer {ans!r} in {sub}")

        if not isinstance(dists, list) or len(dists) != 3:
            errs.append(f"{ctx}: expected 3 distractors")
            dist_texts: list[str] = []
        else:
            dist_texts = [str(d["text"]).strip() if isinstance(d, dict) else str(d).strip() for d in dists]
            all_opts = [ans] + dist_texts
            if len({o.lower() for o in all_opts}) != 4:
                errs.append(f"{ctx}: duplicate options {all_opts}")
            for o in all_opts:
                if not o or RE_LETTER_REF.match(o):
                    errs.append(f"{ctx}: bad option {o!r}")

        if not isinstance(clues, list) or len(clues) != 2:
            errs.append(f"{ctx}: expected 2 clues")
            clues = []

        errs.extend(_check_text(prompt, did, "prompt", ctx))
        errs.extend(_check_text(ans, did, "answerCorrect", ctx))
        for di, dt in enumerate(dist_texts):
            errs.extend(_check_text(dt, did, f"dist[{di}]", ctx))
        for ci, cl in enumerate(clues):
            errs.extend(_check_text(str(cl), did, f"clue[{ci}]", ctx))
        errs.extend(_check_text(why, did, "why", ctx))

        p_low = prompt.lower()
        a_low = ans.lower()
        if len(a_low) >= 4 and a_low in p_low:
            errs.append(f"{ctx}: PROMPT_EXACT_LEAK ans={ans!r}")
        stripped = re.sub(r"^(?:the|a|an|republic of|kingdom of|state of|city of)\s+", "", a_low, flags=re.I).strip()
        if did != 11 and len(stripped) >= 5 and stripped in p_low and _has_word_stem(p_low, stripped):
            errs.append(f"{ctx}: PROMPT_CORE_LEAK ans={ans!r}")
        if did != 11:
            ans_toks = [t for t in re.split(r"[^a-z0-9]+", stripped) if len(t) >= 4 and t not in LEAK_STOPWORDS]
            if len(ans_toks) >= 2:
                all_in = all(_has_word_stem(p_low, _singular_stem(t)) for t in ans_toks)
                dist_also = any(
                    len(dts) >= 2 and all(_has_word_stem(p_low, _singular_stem(t)) for t in dts)
                    for dts in ([t for t in re.split(r"[^a-z0-9]+", dt.lower()) if len(t) >= 4 and t not in LEAK_STOPWORDS] for dt in dist_texts)
                )
                if all_in and not dist_also:
                    errs.append(f"{ctx}: SELF_ANSWERING_TOKENS {ans_toks}")
        for ci, cl in enumerate(clues):
            cl_low = str(cl).lower()
            if len(a_low) >= 4 and a_low in cl_low:
                errs.append(f"{ctx}: CLUE{ci}_EXACT_LEAK ans={ans!r}")
            if did != 11 and len(stripped) >= 5 and stripped in cl_low and _has_word_stem(cl_low, stripped):
                errs.append(f"{ctx}: CLUE{ci}_CORE_LEAK ans={ans!r}")

    # Coverage gates
    if len(by_domain) != 12:
        errs.append(f"Expected 12 domains, got {len(by_domain)}")
    for d in range(12):
        if by_domain[d] < 130:
            errs.append(f"Domain {d}: {by_domain[d]} < 130 minimum")
    if len(by_l1) != len(all_l1_ids):
        errs.append(f"Expected {len(all_l1_ids)} L1 categories, got {len(by_l1)}")
    for sid in ordered_l2s:
        if by_l2[sid] < 8:
            errs.append(f"L2 {sid}: {by_l2[sid]} < 8 minimum")

    return errs


def main() -> int:
    parser = argparse.ArgumentParser(description="Build & verify public/data/jeopardy_signature_packs.json")
    parser.add_argument("--verify", action="store_true", help="Verify existing public/data/jeopardy_signature_packs.json without rewriting")
    args = parser.parse_args()

    if args.verify:
        if not OUT_PATH.exists():
            print(f"FAIL: {OUT_PATH} does not exist")
            return 1
        bundle = json.loads(OUT_PATH.read_text(encoding="utf-8"))
        errs = verify_pack(bundle, check_disk_determinism=True)
    else:
        bundle = build_bundle()
        errs = verify_pack(bundle, check_disk_determinism=False)
        if not errs:
            OUT_PATH.write_text(json.dumps(bundle, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

    if errs:
        print(f"FAIL: {len(errs)} verification error(s):")
        for e in errs[:40]:
            print("  -", e)
        if len(errs) > 40:
            print(f"  ... and {len(errs) - 40} more")
        return 1

    cov = bundle["coverage"]
    qr = bundle["qidRange"]
    print(
        f"PASS: public/data/jeopardy_signature_packs.json — "
        f"{bundle['totalCount']} questions | QIDs {qr[0]}..{qr[1]} | "
        f"{cov['domains']}/12 domains | {cov['l1Categories']}/49 L1s | {cov['l2Subcategories']}/157 L2s | 0 defects!"
    )
    for d in range(12):
        print(f"  D{d:2d}: {bundle['counts']['byDomain'][str(d)]:3d} Qs")
    return 0


